1	//! SPSC ring v4: v3's ring of segments over a ring that describes
2	//! itself in the region, so a second process can attach to it,
3	//! and v3 stays as built to measure against.
4	//!
5	//! - What v4 adds to v3: a control block at the front of segment
6	//!   0 (magic, layout version, geometry, the role claims word, and
7	//!   the table of every segment's pool buffer index), a table of
8	//!   offsets instead of pointers in the endpoints, [`Ring::attach`]
9	//!   from a pool and [`Ring::first_segment`], and the roles taken
10	//!   by name, [`Ring::producer`] and [`Ring::consumer`], each held
11	//!   once anywhere. The protocol below is v3's, unchanged.
12	//! - A ring holds up to [`MAX_SEGMENTS`] segments, each a ring of
13	//!   its own of the same depth, every one taken from the
14	//!   application's pool at [`Ring::init`]. Nothing allocates,
15	//!   frees, or re-initializes while the ring runs.
16	//! - With a consumer that keeps up, the ring lives in one segment
17	//!   and each side loads one seq word per message, as v2 does.
18	//!   The other segments are insurance for a producer that runs
19	//!   ahead, and switching between them is the only cost v3 adds.
20	//! - Slots open with v2's in-slot seq word, 32 bits so v3 builds
21	//!   wherever v0 through v2 do. The low [`SEQ_BITS`] hold v2's
22	//!   claimable `pos`, committed `pos + M + 1`, and released
23	//!   `pos + M`, and the high bits a MOVED flag and the next
24	//!   segment's number, so one load tells the consumer empty, a
25	//!   message, or a message and then segment `k`.
26	//! - The producer decides a switch at its own commit, the one
27	//!   moment it alone writes the slot's word: when the next slot
28	//!   is not claimable it takes a free segment and commits with
29	//!   MOVED. A slot seen claimable stays claimable until the
30	//!   producer claims it, so that look-ahead replaces the next
31	//!   reserve's load.
32	//! - Free segments need no CAS: the producer keeps a private
33	//!   word flipping a segment's bit when it takes it, the consumer
34	//!   a shared word flipping it when it gives it back, so a
35	//!   segment is free where the two agree.
36	//! - Each side keeps a private resume position per segment. Both
37	//!   leave a segment at the same slot, so a reused segment's
38	//!   seqs are already claimable where the producer picks up.
39	//! - Attach is a join, not a resume: an endpoint taken after
40	//!   `attach` starts in segment 0 at position 0, as one taken
41	//!   after `init` does, so a process joins before its role has
42	//!   run.
43	//! - How to use it, from a pool to two threads and to a second
44	//!   process, is the user guide, `notes/user-guide.md`, and what
45	//!   happens to the segments over a run is the design note's
46	//!   Segment lifecycle subsection, v3's and v4's alike.
47	
48	use core::mem::{align_of, size_of};
49	use core::sync::atomic::{AtomicU32, Ordering};
50	
51	use crate::pool::Pool;
52	use crate::{CACHE_LINE_SIZE, CacheAligned, Error};
53	
54	mod consumer;
55	mod producer;
56	
57	pub use crate::spsc::v2::SLOT_HEADER_BYTES;
58	pub use consumer::{Consumer, ReadSlot};
59	pub use producer::{Producer, WriteSlot};
60	
61	/// The most segments a ring holds: one bit each in the free
62	/// words, and five bits of the seq word name one.
63	pub const MAX_SEGMENTS: u32 = 32;
64	
65	/// Seq word bits holding the seq value. The rest carry MOVED
66	/// and the next segment's number.
67	pub const SEQ_BITS: u32 = 26;
68	
69	/// The seq value's bits within the word.
70	const SEQ_MASK: u32 = (1 << SEQ_BITS) - 1;
71	
72	/// Where the next segment's number sits in the word.
73	const SEG_SHIFT: u32 = SEQ_BITS;
74	
75	/// The next segment's number, once shifted down.
76	const SEG_MASK: u32 = MAX_SEGMENTS - 1;
77	
78	/// Set in a committed word whose message is the producer's last
79	/// in its segment.
80	const MOVED: u32 = 1 << 31;
81	
82	/// Segment depth bound: seq values wrap at `2^SEQ_BITS`, and
83	/// claimable, committed, and released must stay distinct.
84	pub const MAX_SEG_CAPACITY: u32 = 1 << 24;
85	
86	const _: () = assert!(SEG_SHIFT + MAX_SEGMENTS.trailing_zeros() <= 31);
87	const _: () = assert!(MAX_SEG_CAPACITY + 1 < SEQ_MASK);
88	
89	/// The seq value for free-running position `idx`, wrapped to
90	/// [`SEQ_BITS`].
91	#[inline]
92	pub(crate) fn seq_of(idx: u32) -> u32 {
93	    idx & SEQ_MASK
94	}
95	
96	/// Layout marker written by [`Ring::init`] into every segment's
97	/// header, distinct from the other rings' and the pools'.
98	const MAGIC: u32 = 0x5A43_5234; // "ZCR4"
99	
100	/// Bumped on any change to the segment layout.
101	const LAYOUT_VERSION: u32 = 1;
102	
103	/// A table entry naming no segment.
104	const NO_SEGMENT: u32 = u32::MAX;
105	
106	/// The producer's bit in the claims word.
107	const PRODUCER_CLAIM: u32 = 1;
108	
109	/// The consumer's bit in the claims word.
110	const CONSUMER_CLAIM: u32 = 2;
111	
112	/// The first line of every segment: which ring it belongs to,
113	/// written by [`Ring::init`] and read back by `attach`.
114	///
115	/// - Every field is a `u32` atomic, so a process reads the line
116	///   with the ordering the magic's Acquire gives it.
117	/// - `given` is the consumer's give-back word, meaningful in
118	///   segment 0 only, the one word both sides share besides the
119	///   slots. It shares the line with the geometry because the
120	///   geometry is read at attach and never after.
121	#[repr(C)]
122	struct Info {
123	    magic: AtomicU32,
124	    layout_version: AtomicU32,
125	    slot_size: AtomicU32,
126	    seg_capacity: AtomicU32,
127	    seg_count: AtomicU32,
128	    /// This segment's number in the ring.
129	    seg_num: AtomicU32,
130	    given: AtomicU32,
131	}
132	
133	/// The four lines at the front of every segment: the ring's
134	/// control block in segment 0, and the same layout in the others
135	/// so every segment's slots start at one offset.
136	///
137	/// - The pool buffer index of each segment is in the table, so a
138	///   process holding the pool and segment 0's index finds every
139	///   segment: the offsets-only rule, applied to the ring's table.
140	/// - The claims word is its own line, so the CAS that takes a
141	///   role never shares a line with `given`.
142	#[repr(C)]
143	struct SegmentHeader {
144	    /// Line 0: the ring's identity and geometry, and `given`.
145	    info: CacheAligned<Info>,
146	    /// Line 1: the role claims word, segment 0's only.
147	    claims: CacheAligned<AtomicU32>,
148	    /// Lines 2 and 3: the pool buffer index of segment `i` at
149	    /// `table[i]`, [`NO_SEGMENT`] past `seg_count`, segment 0's
150	    /// only.
151	    table: CacheAligned<[AtomicU32; MAX_SEGMENTS as usize]>,
152	}
153	
154	const _: () = assert!(size_of::<SegmentHeader>() == 4 * CACHE_LINE_SIZE);
155	
156	/// Bytes a segment needs: its header lines, then the slots.
157	///
158	/// - The pool handed to [`Ring::init`] needs buffers at least
159	///   this large.
160	/// - Computed in u64 for the same 32-bit wrap reason as the
161	///   rings' region sizes.
162	pub fn segment_size(slot_size: u32, seg_capacity: u32) -> u64 {
163	    size_of::<SegmentHeader>() as u64 + slot_size as u64 * seg_capacity as u64
164	}
165	
166	/// A ring's geometry and where its segments are, the state both
167	/// endpoints start from.
168	///
169	/// - The segments are byte offsets from the pool's buffer array,
170	///   the same numbers in every process, and `base` is that array
171	///   in this one, so the table could be shared as it is and a
172	///   slot access is one add over v3's.
173	#[derive(Clone, Copy)]
174	struct Segments {
175	    /// The pool's buffer array in this process.
176	    base: *mut u8,
177	    /// The slot array of each segment, `seg_count` of them, as an
178	    /// offset from `base`.
179	    slots: [usize; MAX_SEGMENTS as usize],
180	    /// Segment 0's header as an offset from `base`: `given` and
181	    /// the claims word live there.
182	    header0: usize,
183	    /// Slot size N in bytes.
184	    slot_size: u32,
185	    /// Segment depth M, a power of two.
186	    capacity: u32,
187	    /// Slot-position mask (`capacity - 1`).
188	    mask: u32,
189	    /// Segments in the ring.
190	    seg_count: u32,
191	}
192	
193	impl Segments {
194	    /// The seq word of the slot at free-running `idx` in segment
195	    /// `seg`.
196	    fn seq(&self, seg: u32, idx: u32) -> &AtomicU32 {
197	        let slot = crate::slot_ptr(self.slot_base(seg), idx, self.mask, self.slot_size);
198	        // SAFETY: seg < seg_count and the slot is in bounds of
199	        // that segment's buffer, line-aligned, so its first word
200	        // is an aligned AtomicU32, shared atomic state by design.
201	        unsafe { &*(slot as *const AtomicU32) }
202	    }
203	
204	    /// The body of the slot at free-running `idx` in segment
205	    /// `seg`, behind its [`SLOT_HEADER_BYTES`].
206	    fn body(&self, seg: u32, idx: u32) -> *mut u8 {
207	        let slot = crate::slot_ptr(self.slot_base(seg), idx, self.mask, self.slot_size);
208	        // SAFETY: SLOT_HEADER_BYTES < CACHE_LINE_SIZE <= slot_size,
209	        // so the body starts inside the slot.
210	        unsafe { slot.add(SLOT_HEADER_BYTES) }
211	    }
212	
213	    /// Segment `seg`'s slot array in this process.
214	    #[inline]
215	    fn slot_base(&self, seg: u32) -> *mut u8 {
216	        // SAFETY: seg < seg_count, and the offset was computed by
217	        // init or attach from a buffer index the pool validated,
218	        // so it stays inside the buffer array.
219	        unsafe { self.base.add(self.slots[seg as usize]) }
220	    }
221	
222	    /// Segment 0's header, the ring's control block.
223	    fn header0(&self) -> &SegmentHeader {
224	        // SAFETY: header0 is the front of segment 0's buffer,
225	        // line-aligned, which lives as long as the pool region the
226	        // ring borrows from, and every field is atomic.
227	        unsafe { &*(self.base.add(self.header0) as *const SegmentHeader) }
228	    }
229	
230	    /// The consumer's give-back word.
231	    fn given(&self) -> &AtomicU32 {
232	        &self.header0().info.given
233	    }
234	
235	    /// The table every endpoint starts from, built the same way
236	    /// by `init` and `attach`: each segment's slot array as an
237	    /// offset from the pool's buffer array.
238	    fn load(
239	        base: *mut u8,
240	        buf_size: usize,
241	        indices: &[u32; MAX_SEGMENTS as usize],
242	        slot_size: u32,
243	        seg_capacity: u32,
244	        seg_count: u32,
245	    ) -> Self {
246	        let mut slots = [0usize; MAX_SEGMENTS as usize];
247	        for seg in 0..seg_count as usize {
248	            slots[seg] = indices[seg] as usize * buf_size + size_of::<SegmentHeader>();
249	        }
250	        Segments {
251	            base,
252	            slots,
253	            header0: indices[0] as usize * buf_size,
254	            slot_size,
255	            capacity: seg_capacity,
256	            mask: seg_capacity - 1,
257	            seg_count,
258	        }
259	    }
260	
261	    /// Release a role's bit in the claims word, the endpoint's
262	    /// drop.
263	    fn release_role(&self, bit: u32) {
264	        // Release: the next claimant's AcqRel sees everything this
265	        // endpoint did.
266	        self.header0().claims.fetch_and(!bit, Ordering::Release);
267	    }
268	
269	    /// Every segment's bit.
270	    fn all(&self) -> u32 {
271	        if self.seg_count == MAX_SEGMENTS {
272	            u32::MAX
273	        } else {
274	            (1 << self.seg_count) - 1
275	        }
276	    }
277	}
