279	/// A ring of segments over the application's pool, split into
280	/// the two endpoint handles with [`Ring::split`].
281	pub struct Ring<'a> {
282	    /// Geometry and segment offsets.
283	    segs: Segments,
284	    /// The pool buffer index of segment 0, where the control
285	    /// block is.
286	    first_segment: u32,
287	    _region: core::marker::PhantomData<&'a [u8]>,
288	}
289	
290	impl<'a> Ring<'a> {
291	    /// Take `seg_count` segments from `pool` and initialize each
292	    /// as an empty ring of `seg_capacity` slots of `slot_size`
293	    /// bytes.
294	    ///
295	    /// - `slot_size`: N bytes per slot, a [`CACHE_LINE_SIZE`]
296	    ///   multiple, of which [`SLOT_HEADER_BYTES`] are the crate's.
297	    /// - `seg_capacity`: M slots per segment, a power of two up to
298	    ///   [`MAX_SEG_CAPACITY`], 1 included.
299	    /// - `seg_count`: 1 to [`MAX_SEGMENTS`].
300	    /// - The pool's buffers must hold [`segment_size`], else
301	    ///   [`Error::TooSmall`]. A pool without `seg_count` free
302	    ///   buffers gives [`Error::Exhausted`], with the buffers
303	    ///   taken so far freed.
304	    /// - The pool is borrowed only here. The segments stay
305	    ///   allocated for the life of the pool region, as a
306	    ///   [`BufSlot`](crate::BufSlot) dropped without `free` does.
307	    /// - Every segment's header names the ring, and segment 0's
308	    ///   holds the table of segments, so a process holding the
309	    ///   pool and [`first_segment`](Ring::first_segment) can find
310	    ///   the ring.
311	    pub fn init(
312	        pool: &mut Pool<'a>,
313	        slot_size: u32,
314	        seg_capacity: u32,
315	        seg_count: u32,
316	    ) -> Result<Self, Error> {
317	        validate_geometry(slot_size, seg_capacity, seg_count)?;
318	        if (pool.buf_size() as u64) < segment_size(slot_size, seg_capacity) {
319	            return Err(Error::TooSmall);
320	        }
321	        let mut taken: [Option<crate::BufSlot<'a, [u8]>>; MAX_SEGMENTS as usize] =
322	            core::array::from_fn(|_| None);
323	        let mut indices = [NO_SEGMENT; MAX_SEGMENTS as usize];
324	        for seg in 0..seg_count as usize {
325	            match pool.alloc_bytes() {
326	                Ok(buf) => {
327	                    indices[seg] = buf.idx();
328	                    taken[seg] = Some(buf);
329	                }
330	                Err(_) => {
331	                    taken.into_iter().flatten().for_each(crate::BufSlot::free);
332	                    return Err(Error::Exhausted);
333	                }
334	            }
335	        }
336	        // The segments stay allocated: their guards go out of
337	        // scope with `taken`, never freed.
338	        let base = pool.bufs_ptr();
339	        let buf_size = pool.buf_size() as usize;
340	        for seg in 0..seg_count as usize {
341	            let offset = indices[seg] as usize * buf_size;
342	            // SAFETY: the offset names a buffer of at least
343	            // segment_size bytes the pool just handed out,
344	            // line-aligned, and nothing else can reach it until a
345	            // role is taken: the header lines and each slot's
346	            // header are ours to write.
347	            unsafe {
348	                let seg_base = base.add(offset);
349	                core::ptr::write_bytes(seg_base, 0, size_of::<SegmentHeader>());
350	                let header = &*(seg_base as *const SegmentHeader);
351	                header
352	                    .info
353	                    .layout_version
354	                    .store(LAYOUT_VERSION, Ordering::Relaxed);
355	                header.info.slot_size.store(slot_size, Ordering::Relaxed);
356	                header
357	                    .info
358	                    .seg_capacity
359	                    .store(seg_capacity, Ordering::Relaxed);
360	                header.info.seg_count.store(seg_count, Ordering::Relaxed);
361	                header.info.seg_num.store(seg as u32, Ordering::Relaxed);
362	                if seg == 0 {
363	                    for (entry, &idx) in header.table.iter().zip(indices.iter()) {
364	                        entry.store(idx, Ordering::Relaxed);
365	                    }
366	                }
367	                let seg_slots = seg_base.add(size_of::<SegmentHeader>());
368	                for i in 0..seg_capacity {
369	                    let slot = seg_slots.add(i as usize * slot_size as usize);
370	                    core::ptr::write_bytes(slot, 0, SLOT_HEADER_BYTES);
371	                    // `seq[i] = i`: every slot claimable for lap 0.
372	                    (*(slot as *const AtomicU32)).store(seq_of(i), Ordering::Relaxed);
373	                }
374	                // The magic last (Release): a reader that sees it
375	                // sees the rest of the block.
376	                header.info.magic.store(MAGIC, Ordering::Release);
377	            }
378	        }
379	        Ok(Ring {
380	            segs: Segments::load(base, buf_size, &indices, slot_size, seg_capacity, seg_count),
381	            first_segment: indices[0],
382	            _region: core::marker::PhantomData,
383	        })
384	    }
385	
386	    /// Join a ring another process (or an earlier call) initialized
387	    /// over `pool`, from the pool buffer index of its segment 0.
388	    ///
389	    /// - Reads the control block, checks every field and every
390	    ///   table entry against the pool's geometry, and every
391	    ///   segment's own header against the block, so a hostile
392	    ///   region is an `Err`, never an out-of-bounds access.
393	    /// - The endpoints then taken start in segment 0 at position
394	    ///   0, as after `init`, so attach is for a process joining
395	    ///   before its role has run. Recovering a mid-run position is
396	    ///   not done here.
397	    ///
398	    /// # Safety
399	    ///
400	    /// - `first_segment` came from [`first_segment`](Ring::first_segment)
401	    ///   of a ring initialized over this pool's region, and its
402	    ///   segments are still the ring's: validation cannot tell a
403	    ///   ring's segment from a buffer since freed and reused, and
404	    ///   the ring writes seq words into every segment it is told
405	    ///   it has.
406	    pub unsafe fn attach(pool: &Pool<'a>, first_segment: u32) -> Result<Self, Error> {
407	        let buf_count = pool.buf_count();
408	        if first_segment >= buf_count {
409	            return Err(Error::BadSegment);
410	        }
411	        let base = pool.bufs_ptr();
412	        let buf_size = pool.buf_size() as usize;
413	        // SAFETY: first_segment < buf_count, so the header is the
414	        // line-aligned front of a buffer inside the pool's region,
415	        // and every field read is atomic.
416	        let block =
417	            unsafe { &*(base.add(first_segment as usize * buf_size) as *const SegmentHeader) };
418	        // Acquire pairs with init's Release store of the magic.
419	        if block.info.magic.load(Ordering::Acquire) != MAGIC {
420	            return Err(Error::BadMagic);
421	        }
422	        if block.info.layout_version.load(Ordering::Relaxed) != LAYOUT_VERSION {
423	            return Err(Error::BadLayoutVersion);
424	        }
425	        let slot_size = block.info.slot_size.load(Ordering::Relaxed);
426	        let seg_capacity = block.info.seg_capacity.load(Ordering::Relaxed);
427	        let seg_count = block.info.seg_count.load(Ordering::Relaxed);
428	        validate_geometry(slot_size, seg_capacity, seg_count)?;
429	        if (buf_size as u64) < segment_size(slot_size, seg_capacity) {
430	            return Err(Error::TooSmall);
431	        }
432	        if block.info.seg_num.load(Ordering::Relaxed) != 0 {
433	            return Err(Error::BadSegment);
434	        }
435	        let mut indices = [NO_SEGMENT; MAX_SEGMENTS as usize];
436	        for seg in 0..seg_count as usize {
437	            let idx = block.table[seg].load(Ordering::Relaxed);
438	            if idx >= buf_count || indices[..seg].contains(&idx) {
439	                return Err(Error::BadSegment);
440	            }
441	            indices[seg] = idx;
442	        }
443	        if indices[0] != first_segment {
444	            return Err(Error::BadSegment);
445	        }
446	        // Every segment's own header must agree with the block.
447	        for (seg, &idx) in indices.iter().enumerate().take(seg_count as usize) {
448	            // SAFETY: idx < buf_count, as checked above.
449	            let info =
450	                unsafe { &(*(base.add(idx as usize * buf_size) as *const SegmentHeader)).info };
451	            let agrees = info.magic.load(Ordering::Acquire) == MAGIC
452	                && info.layout_version.load(Ordering::Relaxed) == LAYOUT_VERSION
453	                && info.slot_size.load(Ordering::Relaxed) == slot_size
454	                && info.seg_capacity.load(Ordering::Relaxed) == seg_capacity
455	                && info.seg_count.load(Ordering::Relaxed) == seg_count
456	                && info.seg_num.load(Ordering::Relaxed) == seg as u32;
457	            if !agrees {
458	                return Err(Error::BadSegment);
459	            }
460	        }
461	        Ok(Ring {
462	            segs: Segments::load(base, buf_size, &indices, slot_size, seg_capacity, seg_count),
463	            first_segment,
464	            _region: core::marker::PhantomData,
465	        })
466	    }
467	
468	    /// Take the producer role.
469	    ///
470	    /// - One CAS on the control block's claims word, so a role
471	    ///   held anywhere, in this process or another, is
472	    ///   [`Error::RoleTaken`], and dropping the endpoint releases
473	    ///   it. Nothing on the message path reads the word.
474	    /// - Starts in segment 0 at position 0, which it holds as
475	    ///   taken.
476	    pub fn producer(&self) -> Result<Producer<'a>, Error> {
477	        self.claim(PRODUCER_CLAIM)?;
478	        Ok(Producer::new(self.segs))
479	    }
480	
481	    /// Take the consumer role, the counterpart of
482	    /// [`producer`](Ring::producer).
483	    pub fn consumer(&self) -> Result<Consumer<'a>, Error> {
484	        self.claim(CONSUMER_CLAIM)?;
485	        Ok(Consumer::new(self.segs))
486	    }
487	
488	    /// Set `bit` in the claims word, unless it was set.
489	    fn claim(&self, bit: u32) -> Result<(), Error> {
490	        // AcqRel: a claim that succeeds sees the state a released
491	        // endpoint left, and its own release publishes the same.
492	        // Setting a set bit changes nothing, so a failure needs no
493	        // undo.
494	        let before = self.segs.header0().claims.fetch_or(bit, Ordering::AcqRel);
495	        if before & bit != 0 {
496	            return Err(Error::RoleTaken);
497	        }
498	        Ok(())
499	    }
500	
501	    /// The pool buffer index of segment 0, where the ring's
502	    /// control block is: what a process hands to another so it
503	    /// can find the ring in the same pool.
504	    pub fn first_segment(&self) -> u32 {
505	        self.first_segment
506	    }
507	}
508	
509	/// Geometry checks for [`Ring::init`].
510	pub(crate) fn validate_geometry(
511	    slot_size: u32,
512	    seg_capacity: u32,
513	    seg_count: u32,
514	) -> Result<(), Error> {
515	    if slot_size == 0 || !(slot_size as usize).is_multiple_of(CACHE_LINE_SIZE) {
516	        return Err(Error::BadSlotSize);
517	    }
518	    if seg_capacity == 0 || !seg_capacity.is_power_of_two() || seg_capacity > MAX_SEG_CAPACITY {
519	        return Err(Error::BadCapacity);
520	    }
521	    if seg_count == 0 || seg_count > MAX_SEGMENTS {
522	        return Err(Error::BadSegmentCount);
523	    }
524	    Ok(())
525	}
526	
527	/// Check `T` fits a slot's body, called once per
528	/// `reserve_slot_with` (both endpoints), as v2 checks.
529	pub(crate) fn check_body_type<T>(slot_size: u32) {
530	    assert!(
531	        size_of::<T>() <= slot_size as usize - SLOT_HEADER_BYTES,
532	        "T larger than the slot body"
533	    );
534	    assert!(
535	        align_of::<T>() <= SLOT_HEADER_BYTES,
536	        "T alignment exceeds the slot body's"
537	    );
538	}
