836	    fn positions_survive_u32_wrap() {
837	        // Both sides two commits shy of the u32 wrap in every
838	        // segment, each segment's seqs claimable for the lap that
839	        // starts there, then several laps across it.
840	        let mut r = Region::new();
841	        let mut pool = Pool::init(&mut r.0, BUF as u32, BUFS as u32).unwrap();
842	        let ring = Ring::init(&mut pool, 64, 4, 3).unwrap();
843	        let start = u32::MAX - 1;
844	        for seg in 0..3 {
845	            for i in 0..4u32 {
846	                let idx = start.wrapping_add(i);
847	                ring.segs
848	                    .seq(seg, idx)
849	                    .store(seq_of(idx), Ordering::Relaxed);
850	            }
851	        }
852	        let (mut prod, mut cons) = endpoints(&ring);
853	        for st_pos in [&mut prod.st.pos, &mut cons.st.pos] {
854	            *st_pos = start;
855	        }
856	        prod.st.resume = [start; MAX_SEGMENTS as usize];
857	        cons.st.resume = [start; MAX_SEGMENTS as usize];
858	        // Batches of at most the ring's 12, so no send finds Full.
859	        for (from, to) in [(0u64, 12u64), (12, 24), (24, 30), (30, 41)] {
860	            send(&mut prod, from, to);
861	            recv(&mut cons, from, to);
862	            assert_eq!(free_segments(&prod).count_ones(), 2);
863	        }
864	        // The positions did cross the wrap.
865	        assert!(prod.st.pos < start && cons.st.pos < start);
866	    }
