922	    /// Attach a pool handle over `base`.
923	    fn attach_pool<'a>(base: *mut u8, len: usize) -> Pool<'a> {
924	        // SAFETY: the same live region, and no attached handle
925	        // allocates, so no second popper exists.
926	        unsafe { Pool::attach(base, len) }.unwrap()
927	    }
