939	        let (b1, b2) = (attach_pool(base, len), attach_pool(base, len));
940	        // SAFETY: the indices came from first_segment of rings over
941	        // this pool, whose segments are still the rings'.
942	        let ring_1 = unsafe { Ring::attach(&b1, first) }.unwrap();
943	        let ring_2 = unsafe { Ring::attach(&b2, first) }.unwrap();
944	        assert_eq!(ring_2.first_segment(), first);
945	        assert_eq!(ring_2.segs.slots, ring_1.segs.slots);
946	
