980	    #[test]
981	    fn attach_rejects_hostile_control_blocks() {
982	        let mut r = Region::new();
983	        let (base, len) = region(&mut r);
984	        let (first, spare) = with_init_pool(base, len, |pool| {
985	            let ring = Ring::init(pool, 64, 4, 3).unwrap();
986	            // A buffer that is no segment: free, its first word the
987	            // free-stack link.
988	            let spare = pool.alloc_bytes().unwrap();
989	            let spare_idx = spare.idx();
990	            spare.free();
991	            (ring.first_segment(), spare_idx)
992	        });
993	        let b = attach_pool(base, len);
994	        let attach = |idx| unsafe { Ring::attach(&b, idx) }.err();
995	        // SAFETY: first names the ring's segment 0.
996	        let ring = unsafe { Ring::attach(&b, first) }.unwrap();
997	        let block = ring.segs.header0();
998	
999	        // Not a buffer of the pool, and a buffer that is no segment.
1000	        assert_eq!(attach(BUFS as u32), Some(Error::BadSegment));
1001	        assert_eq!(attach(spare), Some(Error::BadMagic));
1002	
1003	        // A field at a time, restored after each.
1004	        let version = &block.info.layout_version;
1005	        version.store(LAYOUT_VERSION + 1, Ordering::Relaxed);
1006	        assert_eq!(attach(first), Some(Error::BadLayoutVersion));
1007	        version.store(LAYOUT_VERSION, Ordering::Relaxed);
1008	
1009	        block.info.slot_size.store(63, Ordering::Relaxed);
1010	        assert_eq!(attach(first), Some(Error::BadSlotSize));
1011	        block.info.slot_size.store(64, Ordering::Relaxed);
1012	
1013	        block.info.seg_count.store(0, Ordering::Relaxed);
1014	        assert_eq!(attach(first), Some(Error::BadSegmentCount));
1015	        block.info.seg_count.store(3, Ordering::Relaxed);
1016	
1017	        // A segment the pool's buffers cannot hold.
1018	        block.info.seg_capacity.store(32, Ordering::Relaxed);
1019	        assert_eq!(attach(first), Some(Error::TooSmall));
1020	        block.info.seg_capacity.store(4, Ordering::Relaxed);
1021	
1022	        // Segment 0 claiming to be another segment.
1023	        block.info.seg_num.store(1, Ordering::Relaxed);
1024	        assert_eq!(attach(first), Some(Error::BadSegment));
1025	        block.info.seg_num.store(0, Ordering::Relaxed);
1026	
1027	        // A table naming a buffer outside the pool, one twice, and
1028	        // two whose headers are each other's.
1029	        let second = block.table[1].load(Ordering::Relaxed);
1030	        let third = block.table[2].load(Ordering::Relaxed);
1031	        block.table[1].store(BUFS as u32, Ordering::Relaxed);
1032	        assert_eq!(attach(first), Some(Error::BadSegment));
1033	        block.table[1].store(first, Ordering::Relaxed);
1034	        assert_eq!(attach(first), Some(Error::BadSegment));
1035	        block.table[1].store(third, Ordering::Relaxed);
1036	        block.table[2].store(second, Ordering::Relaxed);
1037	        assert_eq!(attach(first), Some(Error::BadSegment));
1038	        block.table[1].store(second, Ordering::Relaxed);
1039	        block.table[2].store(third, Ordering::Relaxed);
1040	
1041	        // Restored, it attaches.
1042	        assert!(unsafe { Ring::attach(&b, first) }.is_ok());
1043	    }
1044	
1045	    fn matrix() -> (Vec<u32>, Vec<u32>) {
1046	        if cfg!(miri) {
1047	            (vec![1, 2, 32], vec![1, 8])
1048	        } else {
1049	            ((1..=MAX_SEGMENTS).collect(), vec![1, 8, 64, 1024])
1050	        }
1051	    }
1052	
1053	    /// Run `f` on a ring of `count` segments of `depth` one-line
1054	    /// slots over a pool holding exactly those segments.
1055	    fn with_ring(count: u32, depth: u32, f: impl FnOnce(Producer<'_>, Consumer<'_>)) {
1056	        let buf = segment_size(64, depth);
1057	        let bytes = size_of::<PoolHeader>() as u64 + buf * count as u64;
1058	        let mut store = vec![Line([0; CACHE_LINE_SIZE]); bytes.div_ceil(64) as usize];
1059	        let mut pool = Pool::init(store.as_mut_slice().as_mut_bytes(), buf as u32, count).unwrap();
1060	        let (prod, cons) = endpoints(&Ring::init(&mut pool, 64, depth, count).unwrap());
1061	        f(prod, cons);
1062	    }
1063	
1064	    #[test]
1065	    fn every_count_and_depth_fills_and_drains() {
1066	        // With the consumer idle the producer writes into every
1067	        // segment in turn, switching once between each pair, and
1068	        // the consumer follows it through the same switches.
1069	        let (counts, depths) = matrix();
1070	        for &count in &counts {
1071	            for &depth in &depths {
1072	                with_ring(count, depth, |mut prod, mut cons| {
1073	                    let total = (count * depth) as u64;
1074	                    let mut used = 1u32 << prod.segment();
1075	                    for i in 0..total {
1076	                        send(&mut prod, i, i + 1);
1077	                        used |= 1 << prod.segment();
1078	                    }
1079	                    assert_eq!(prod.reserve_slot_with::<Msg>(|_| false).err(), Some(Full));
1080	                    assert_eq!(
1081	                        used.count_ones(),
1082	                        count,
1083	                        "{count} segments at depth {depth}"
1084	                    );
1085	                    assert_eq!(prod.switches(), (count - 1) as u64);
1086	                    recv(&mut cons, 0, total);
1087	                    assert_eq!(cons.reserve_slot_with::<Msg>(|_| false).err(), Some(Empty));
1088	                    assert_eq!(cons.switches(), prod.switches());
1089	                    assert_eq!(cons.segment(), prod.segment());
1090	                    assert_eq!(free_segments(&prod).count_ones(), count - 1);
1091	                });
1092	            }
1093	        }
1094	    }
1095	
1096	    #[test]
1097	    fn every_count_and_depth_survives_uneven_bursts() {
1098	        // Bursts of every size up to the ring's capacity leave
1099	        // segments mid-lap, and after each drain both ends agree.
1100	        let (counts, depths) = matrix();
1101	        let rounds = if cfg!(miri) { 5 } else { 40 };
1102	        for &count in &counts {
1103	            for &depth in &depths {
1104	                with_ring(count, depth, |mut prod, mut cons| {
1105	                    let capacity = (count * depth) as u64;
1106	                    let mut next = 0u64;
1107	                    for round in 0..rounds {
1108	                        let n = 1 + (round * 7919) % capacity;
1109	                        send(&mut prod, next, next + n);
1110	                        recv(&mut cons, next, next + n);
1111	                        next += n;
1112	                        assert_eq!(cons.switches(), prod.switches());
1113	                        assert_eq!(free_segments(&prod).count_ones(), count - 1);
1114	                    }
1115	                });
1116	            }
1117	        }
1118	    }
1119	
1120	    #[test]
1121	    fn every_count_and_depth_streams_across_threads() {
1122	        // A producer and a consumer on their own threads, both
1123	        // spinning: order holds and the switch counts agree.
1124	        let (counts, depths) = matrix();
1125	        let total: u64 = if cfg!(miri) { 50 } else { 10_000 };
1126	        for &count in &counts {
1127	            for &depth in &depths {
1128	                with_ring(count, depth, |mut prod, mut cons| {
1129	                    let (sent, seen) = std::thread::scope(|s| {
1130	                        let producer = s.spawn(move || {
1131	                            for i in 0..total {
1132	                                let mut slot =
1133	                                    prod.reserve_slot_with::<Msg>(crate::policy::spin).unwrap();
1134	                                slot.seq = i;
1135	                                slot.commit();
1136	                            }
1137	                            prod.switches()
1138	                        });
1139	                        let consumer = s.spawn(move || {
1140	                            for i in 0..total {
1141	                                let msg =
1142	                                    cons.reserve_slot_with::<Msg>(crate::policy::spin).unwrap();
1143	                                assert_eq!(msg.seq, i);
1144	                                msg.release();
1145	                            }
1146	                            cons.switches()
1147	                        });
1148	                        (producer.join().unwrap(), consumer.join().unwrap())
1149	                    });
1150	                    assert_eq!(sent, seen, "{count} segments at depth {depth}");
1151	                    if depth == 1 && count > 1 {
1152	                        // Every commit at depth 1 finds its one
1153	                        // slot taken, so it switches when it can.
1154	                        assert!(sent > 0);
1155	                    }
1156	                });
1157	            }
1158	        }
1159	    }
1160	
1161	    /// The two-thread stream through `count` segments of depth
1162	    /// `cap`, `total` messages, spinning on both ends.
1163	    fn threaded(cap: u32, count: u32, total: u64) {
1164	        let mut r = Region::new();
1165	        let mut pool = Pool::init(&mut r.0, BUF as u32, BUFS as u32).unwrap();
1166	        let (mut prod, mut cons) = endpoints(&Ring::init(&mut pool, 64, cap, count).unwrap());
1167	        std::thread::scope(|s| {
1168	            s.spawn(move || {
1169	                for i in 0..total {
1170	                    let mut slot = prod.reserve_slot_with::<Msg>(crate::policy::spin).unwrap();
1171	                    slot.seq = i;
1172	                    slot.val = i * 3;
1173	                    slot.commit();
1174	                }
1175	            });
1176	            s.spawn(move || {
1177	                for i in 0..total {
1178	                    let msg = cons.reserve_slot_with::<Msg>(crate::policy::spin).unwrap();
1179	                    assert_eq!(msg.seq, i);
1180	                    assert_eq!(msg.val, i * 3);
1181	                    msg.release();
1182	                }
1183	            });
1184	        });
1185	    }
1186	
1187	    #[test]
1188	    fn threaded_segments() {
1189	        // Reduced under Miri: interpreted spin loops are slow,
1190	        // and its scheduler explores interleavings at any count.
1191	        const TOTAL: u64 = if cfg!(miri) { 200 } else { 100_000 };
1192	        for (cap, count) in [(1u32, 2u32), (1, 3), (2, 2), (4, 3), (16, 2)] {
1193	            threaded(cap, count, TOTAL);
1194	        }
1195	    }
